    "openingScenario": "Dev saw his friend Rohit talking and laughing with two other boys in the corridor. Dev immediately assumed: 'Rohit is making fun of my haircut and turning everyone against me!'",
    "explanation": "Our brains love creating dramatic stories! A fact is something a video camera can record: 'Rohit was laughing with two boys.' An assumption is a story your brain made up: 'They are laughing at me.' Testing your assumptions against real facts prevents 90% of friendship misunderstandings.",
    "stepByStep": [
      "Notice when your chest feels tight or you feel angry/hurt.",
      "Write down your immediate thought: 'They hate me and are mocking me.'",
      "Apply the Camera Test: What would a security camera actually record? (Three boys talking by lockers).",
      "Ask: What evidence do I have for my assumption? (Zero concrete evidence).",
      "Brainstorm 2 alternative realistic explanations: 'They were probably sharing a funny cartoon or talking about football.'",
      "If genuinely concerned, ask a neutral clarifying question later: 'Hey Rohit, what was so funny at lockers earlier?'"
    ],
    "workedExample": {
      "title": "Dev's Camera Test",
      "scenario": "Dev tests his assumption about Rohit.",
      "steps": [
        "Recognizes he is mind-reading without proof.",
        "Applies Camera Test: Rohit smiled and looked at his phone, not at Dev.",
        "Decides not to send an angry text message.",
        "At lunch, Rohit says: 'Dev! Look at this hilarious dog video my cousin sent me this morning!'",
        "Dev realizes his emotional assumption was 100% false."
      ],
      "takeaway": "Pausing to verify facts before reacting prevents destroying good friendships over imaginary stories."
    },
    "commonMistakes": [
      {
        "mistake": "Treating your feelings as proof: 'I feel rejected, therefore they must be excluding me.'",
        "correction": "Emotions are signals, not verified facts; never use feelings to judge reality without evidence."
      },
      {
        "mistake": "Spreading rumors based on unverified assumptions about a classmate.",
        "correction": "Passing on gossip harms innocent people; only share what you personally know to be verified true."
      }
    ],
    "decisionChecklist": [
      "What are the cold, observable facts recorded by a camera?",
      "What story is my brain making up about those facts?",
      "Do I have actual evidence, or am I mind-reading?",
      "What are 2 other plausible reasons for their behavior?"
    ],
    "reflectionPrompt": "Have you ever been completely convinced someone was angry with you, only to find out they were just tired or thinking about something else?",
    "summaryTakeaway": "Test the facts, drop the fiction: the camera test protects you from imaginary conflicts and emotional drama.",
