    "whyItMatters": "Using simple passwords like 'password123', 'admin', or your pet's name leaves your email, school portal, and gaming accounts vulnerable to brute-force hacking in under 2 seconds. A 4-word passphrase creates mathematical invulnerability.",
    "learningObjectives": [
      "Explain why length beats complexity: why a 16-character passphrase is 10,000x stronger than a complex 8-character password",
      "Construct a memorable 4-word passphrase using random concrete nouns, numbers, and symbols",
      "Explain why passwords must NEVER be shared with friends or entered on public cyber caf\u00e9 computers",
      "Demonstrate how to securely store passphrases in an offline master notebook"
    ],
