    "reflectionPrompt": "How does seeing all your clothes neatly displayed in a drawer make choosing an outfit in the morning fast and fun?",
    "summaryTakeaway": "Fold it flat, stand it tall: vertical folding turns drawer chaos into an orderly, peaceful wardrobe library.",
