        "Executes 3 Physiological Sighs in his school desk.",
        "Rolls shoulders backwards 5 times.",
        "Heart rate slows from 110 bpm to 78 bpm in 90 seconds.",
        "Reads the exam paper with calm, laser-focused clarity."
